static class Node { int v; Node l,r; Node(int x){v=x;} }
static int size(Node n){ return n==null ? 0 : 1+size(n.l)+size(n.r); }
public static void main(String[] args){
    Node root=new Node(1); root.l=new Node(2); root.r=new Node(3);
    System.out.println(size(root));
}

static class Node { int v; Node l,r; Node(int x){v=x;} }
static boolean has(Node n,int x){
    if(n==null) return false;
    if(n.v==x) return true;
    return x<n.v ? has(n.l,x) : has(n.r,x);
}
public static void main(String[] args){
    Node r=new Node(5); r.l=new Node(2); r.r=new Node(8);
    System.out.println(has(r,8));
}

