static long power(long a,int b){
    if(b==0) return 1;
    long half=power(a,b/2);
    return b%2==0 ? half*half : half*half*a;
}
public static void main(String[] args){ System.out.println(power(2,10)); }

static void bits(String s,int n){
    if(s.length()==n){ System.out.println(s); return; }
    bits(s+"0",n); bits(s+"1",n);
}
